/*
 Problem: 4020. Elevator Requests I
 Language: cpp
 Runtime: 0 ms (100.00%)
 Memory: 30.9 MB (55.85%)
 Tags: Array, Simulation
*/
class Solution {
public:
    int elevatorRequests(int n, vector<int>& requests) {
        int ans = requests[0];

        for (int i = 1; i < requests.size(); ++i) {
            ans += abs(requests[i] - requests[i - 1]);
        }

        return ans;
    }
};
